INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 50, 'theory', 'Quiz: packages, environments and uv');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 0, 'Why do we need a virtual environment?', '["To make the program run faster", "To isolate a project''s dependencies from the system and from other projects", "To encrypt the code", "To run the program without Python"]', 1, 'Each project gets its own interpreter and its own packages; project libraries are not installed into the system Python.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 1, 'What does a lock file (for example, uv.lock) store?', '["Only direct dependencies, without versions", "The project''s source code", "Exact versions and checksums of all packages, including transitive ones", "Passwords and keys"]', 2, 'It makes the build reproducible on any machine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 2, 'Where does a modern project describe its name, version, dependencies and tool settings?', '["In pyproject.toml", "In setup.cfg", "In requirements.txt", "In README.md"]', 0, 'pyproject.toml replaced the scattering of setup.py, setup.cfg and requirements.txt.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 3, 'What does the version condition ~=1.4.2 mean?', '["Exactly 1.4.2", "Any version except 1.4.2", "No higher than 1.4.2", "Compatible release: >=1.4.2 and ==1.4.*"]', 3, 'Fixes within the 1.4 branch are allowed, but not 1.5.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 4, 'Why are dependencies installed in a Dockerfile before the code is copied?', '["Python requires it", "Dependencies change less often than code and are cached as a separate layer", "It makes the image bigger", "Otherwise uv won''t start"]', 1, 'When the code changes, the layer with the dependencies is not rebuilt.');
